export interface ConnectorConfig {
  /** Pipedrive API token from environment variable PIPEDRIVE_API_TOKEN */
  pipedriveApiToken: string
  /** Pipedrive company domain (e.g., 'mycompany' for mycompany.pipedrive.com) */
  pipedriveCompanyDomain: string
  /** Typeform field ID for the email field */
  typeformEmailFieldId: string
  /** Typeform field ID for the name field */
  typeformNameFieldId: string
  /** Typeform field ID for the company field */
  typeformCompanyFieldId: string
  /** Typeform field ID for the phone field */
  typeformPhoneFieldId: string
  /** Optional injected fetch for testing */
  fetch?: typeof fetch
}

export interface TypeformWebhookPayload {
  event_id: string
  event_type: string
  form_response: {
    form_id: string
    token: string
    submitted_at: string
    answers: Array<{
      type: string
      email?: string
      text?: string
      phone?: string
      field: {
        id: string
        type: string
      }
    }>
  }
}

export interface HandleResult {
  organizationId: number
  personId: number
  dealId: number
}

function extractAnswer(
  answers: TypeformWebhookPayload['form_response']['answers'],
  fieldId: string,
  expectedType: string
): string | undefined {
  const answer = answers.find((a) => a.field.id === fieldId && a.field.type === expectedType)
  if (!answer) return undefined
  switch (expectedType) {
    case 'email':
      return answer.email
    case 'short_text':
      return answer.text
    case 'phone':
      return answer.phone
    default:
      return answer.text
  }
}

async function pipedriveRequest<T>(
  config: ConnectorConfig,
  path: string,
  method: string,
  body: unknown
): Promise<T> {
  const fetchImpl = config.fetch ?? fetch
  const url = `https://${config.pipedriveCompanyDomain}.pipedrive.com/api/v2${path}?api_token=${encodeURIComponent(config.pipedriveApiToken)}`
  const response = await fetchImpl(url, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  })
  if (!response.ok) {
    throw new Error(`Pipedrive API error: ${response.status} ${response.statusText} for ${method} ${path}`)
  }
  return response.json() as Promise<T>
}

export async function handle(payload: TypeformWebhookPayload, config: ConnectorConfig): Promise<HandleResult> {
  // Validate required config
  if (!config.pipedriveApiToken) throw new Error('Missing required config: pipedriveApiToken')
  if (!config.pipedriveCompanyDomain) throw new Error('Missing required config: pipedriveCompanyDomain')
  if (!config.typeformEmailFieldId) throw new Error('Missing required config: typeformEmailFieldId')
  if (!config.typeformNameFieldId) throw new Error('Missing required config: typeformNameFieldId')
  if (!config.typeformCompanyFieldId) throw new Error('Missing required config: typeformCompanyFieldId')
  if (!config.typeformPhoneFieldId) throw new Error('Missing required config: typeformPhoneFieldId')

  const answers = payload.form_response.answers

  // Extract fields from Typeform payload
  const email = extractAnswer(answers, config.typeformEmailFieldId, 'email')
  const name = extractAnswer(answers, config.typeformNameFieldId, 'short_text')
  const company = extractAnswer(answers, config.typeformCompanyFieldId, 'short_text')
  const phone = extractAnswer(answers, config.typeformPhoneFieldId, 'phone')

  // Validate required fields from payload
  if (!email) throw new Error(`Missing required field: email (field ID ${config.typeformEmailFieldId})`)
  if (!name) throw new Error(`Missing required field: name (field ID ${config.typeformNameFieldId})`)
  if (!company) throw new Error(`Missing required field: company (field ID ${config.typeformCompanyFieldId})`)

  // 1. Create organization
  const orgResponse = await pipedriveRequest<{ data: { id: number } }>(
    config,
    '/organizations',
    'POST',
    { name: company }
  )
  const organizationId = orgResponse.data.id

  // 2. Create person linked to organization
  const personResponse = await pipedriveRequest<{ data: { id: number } }>(
    config,
    '/persons',
    'POST',
    {
      name,
      email: [{ value: email, label: 'work' }],
      phone: phone ? [{ value: phone, label: 'work' }] : [],
      org_id: organizationId,
    }
  )
  const personId = personResponse.data.id

  // 3. Create deal linked to person
  const dealResponse = await pipedriveRequest<{ data: { id: number } }>(
    config,
    '/deals',
    'POST',
    {
      title: `Deal from Typeform`,
      person_id: personId,
    }
  )
  const dealId = dealResponse.data.id

  return { organizationId, personId, dealId }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, TypeformWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      pipedriveApiToken: 'test-token',
      pipedriveCompanyDomain: 'testcompany',
      typeformEmailFieldId: 'SMEUb7VJz92Q',
      typeformNameFieldId: 'JwWggjAKtOkA',
      typeformCompanyFieldId: 'some_company_field_id',
      typeformPhoneFieldId: 'some_phone_field_id',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as TypeformWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result).toEqual({ organizationId: 12345, personId: 67890, dealId: 54321 })
  })
})

describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    pipedriveApiToken: 'test-token',
    pipedriveCompanyDomain: 'testcompany',
    typeformEmailFieldId: 'SMEUb7VJz92Q',
    typeformNameFieldId: 'JwWggjAKtOkA',
    typeformCompanyFieldId: 'some_company_field_id',
    typeformPhoneFieldId: 'some_phone_field_id',
  }

  const basePayload: TypeformWebhookPayload = {
    event_id: 'evt-1',
    event_type: 'form_response',
    form_response: {
      form_id: 'form-1',
      token: 'token-1',
      submitted_at: '2024-01-01T00:00:00Z',
      answers: [
        { type: 'email', email: 'test@example.com', field: { id: 'SMEUb7VJz92Q', type: 'email' } },
        { type: 'text', text: 'John Doe', field: { id: 'JwWggjAKtOkA', type: 'short_text' } },
        { type: 'text', text: 'Acme Inc', field: { id: 'some_company_field_id', type: 'short_text' } },
        { type: 'phone', phone: '+15551234567', field: { id: 'some_phone_field_id', type: 'phone' } },
      ],
    },
  }

  it('creates organization, person, and deal on happy path', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.includes('/organizations')) return jsonResponse({ data: { id: 111 } }, 201)
      if (req.url.includes('/persons')) return jsonResponse({ data: { id: 222 } }, 201)
      if (req.url.includes('/deals')) return jsonResponse({ data: { id: 333 } }, 201)
      return jsonResponse({ error: 'not found' }, 404)
    })

    const result = await handle(basePayload, { ...baseConfig, fetch })
    expect(result).toEqual({ organizationId: 111, personId: 222, dealId: 333 })

    expect(calls).toHaveLength(3)
    // Organization creation
    expect(calls[0].method).toBe('POST')
    expect(calls[0].url).toContain('/organizations')
    expect(calls[0].json).toEqual({ name: 'Acme Inc' })
    // Person creation
    expect(calls[1].method).toBe('POST')
    expect(calls[1].url).toContain('/persons')
    expect(calls[1].json).toEqual({
      name: 'John Doe',
      email: [{ value: 'test@example.com', label: 'work' }],
      phone: [{ value: '+15551234567', label: 'work' }],
      org_id: 111,
    })
    // Deal creation
    expect(calls[2].method).toBe('POST')
    expect(calls[2].url).toContain('/deals')
    expect(calls[2].json).toEqual({ title: 'Deal from Typeform', person_id: 222 })
  })

  it('includes api_token as query parameter in all requests', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.includes('/organizations')) return jsonResponse({ data: { id: 1 } }, 201)
      if (req.url.includes('/persons')) return jsonResponse({ data: { id: 2 } }, 201)
      if (req.url.includes('/deals')) return jsonResponse({ data: { id: 3 } }, 201)
      return jsonResponse({ error: 'not found' }, 404)
    })

    await handle(basePayload, { ...baseConfig, fetch })

    for (const call of calls) {
      expect(call.url).toContain('api_token=test-token')
    }
  })

  it('throws when email field is missing from payload', async () => {
    const payloadMissingEmail: TypeformWebhookPayload = {
      ...basePayload,
      form_response: {
        ...basePayload.form_response,
        answers: basePayload.form_response.answers.filter((a) => a.field.id !== 'SMEUb7VJz92Q'),
      },
    }

    const { fetch } = fakeFetch(() => jsonResponse({ data: { id: 1 } }, 201))
    await expect(handle(payloadMissingEmail, { ...baseConfig, fetch })).rejects.toThrow(
      'Missing required field: email'
    )
  })

  it('throws when name field is missing from payload', async () => {
    const payloadMissingName: TypeformWebhookPayload = {
      ...basePayload,
      form_response: {
        ...basePayload.form_response,
        answers: basePayload.form_response.answers.filter((a) => a.field.id !== 'JwWggjAKtOkA'),
      },
    }

    const { fetch } = fakeFetch(() => jsonResponse({ data: { id: 1 } }, 201))
    await expect(handle(payloadMissingName, { ...baseConfig, fetch })).rejects.toThrow(
      'Missing required field: name'
    )
  })

  it('throws when company field is missing from payload', async () => {
    const payloadMissingCompany: TypeformWebhookPayload = {
      ...basePayload,
      form_response: {
        ...basePayload.form_response,
        answers: basePayload.form_response.answers.filter((a) => a.field.id !== 'some_company_field_id'),
      },
    }

    const { fetch } = fakeFetch(() => jsonResponse({ data: { id: 1 } }, 201))
    await expect(handle(payloadMissingCompany, { ...baseConfig, fetch })).rejects.toThrow(
      'Missing required field: company'
    )
  })

  it('throws on non-2xx response from Pipedrive organizations endpoint', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))
    await expect(handle(basePayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Pipedrive API error: 401 Unauthorized for POST /organizations'
    )
  })

  it('throws on non-2xx response from Pipedrive persons endpoint', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.includes('/organizations')) return jsonResponse({ data: { id: 1 } }, 201)
      return jsonResponse({ error: 'Forbidden' }, 403)
    })
    await expect(handle(basePayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Pipedrive API error: 403 Forbidden for POST /persons'
    )
  })

  it('throws on non-2xx response from Pipedrive deals endpoint', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.includes('/organizations')) return jsonResponse({ data: { id: 1 } }, 201)
      if (req.url.includes('/persons')) return jsonResponse({ data: { id: 2 } }, 201)
      return jsonResponse({ error: 'Internal Server Error' }, 500)
    })
    await expect(handle(basePayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Pipedrive API error: 500 Internal Server Error for POST /deals'
    )
  })

  it('creates person without phone when phone field is missing', async () => {
    const payloadNoPhone: TypeformWebhookPayload = {
      ...basePayload,
      form_response: {
        ...basePayload.form_response,
        answers: basePayload.form_response.answers.filter((a) => a.field.id !== 'some_phone_field_id'),
      },
    }

    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.includes('/organizations')) return jsonResponse({ data: { id: 1 } }, 201)
      if (req.url.includes('/persons')) return jsonResponse({ data: { id: 2 } }, 201)
      if (req.url.includes('/deals')) return jsonResponse({ data: { id: 3 } }, 201)
      return jsonResponse({ error: 'not found' }, 404)
    })

    const result = await handle(payloadNoPhone, { ...baseConfig, fetch })
    expect(result).toEqual({ organizationId: 1, personId: 2, dealId: 3 })

    const personCall = calls.find((c) => c.url.includes('/persons'))
    expect(personCall).toBeDefined()
    expect(personCall!.json).toEqual({
      name: 'John Doe',
      email: [{ value: 'test@example.com', label: 'work' }],
      phone: [],
      org_id: 1,
    })
  })

  it('validates required config fields', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ data: { id: 1 } }, 201))

    await expect(handle(basePayload, { ...baseConfig, pipedriveApiToken: '', fetch })).rejects.toThrow(
      'Missing required config: pipedriveApiToken'
    )
    await expect(handle(basePayload, { ...baseConfig, pipedriveCompanyDomain: '', fetch })).rejects.toThrow(
      'Missing required config: pipedriveCompanyDomain'
    )
    await expect(handle(basePayload, { ...baseConfig, typeformEmailFieldId: '', fetch })).rejects.toThrow(
      'Missing required config: typeformEmailFieldId'
    )
    await expect(handle(basePayload, { ...baseConfig, typeformNameFieldId: '', fetch })).rejects.toThrow(
      'Missing required config: typeformNameFieldId'
    )
    await expect(handle(basePayload, { ...baseConfig, typeformCompanyFieldId: '', fetch })).rejects.toThrow(
      'Missing required config: typeformCompanyFieldId'
    )
    await expect(handle(basePayload, { ...baseConfig, typeformPhoneFieldId: '', fetch })).rejects.toThrow(
      'Missing required config: typeformPhoneFieldId'
    )
  })
})

